let colors = ['#f0101c', '#f05697', '#0b469b', '#32b6c3', '#f78000', '#fddf0e', '#9fe063', '#315423', '#16141b','#ffffff'];

let contours = [];

let border = -100;

function setup() {
	createCanvas(800,800);
	colorMode(HSB, 360, 100, 100, 100);
	background(0);
	pixelDensity(1);

	for(let xx=border;xx <= width-border;xx+=100)
	{
		for(let yy=border;yy <= height-border;yy+=100)
		{
			let size1 = random(10,250);
		  let size2 = size1/2.0;
		  contours.push(new contour(xx,yy,size1,size2));
		}
  }

	smooth(8);

}


function draw() {

	if(frameCount > 2000) 
	{
     // noLoop() removed for animation
	}

	for(let i=0;i < contours.length;i++)
	{
		contours[i].move();
	  contours[i].display();
	}

}


class contour
{
	constructor(x,y,mySize1,mySize2)
	{
		this.x = x;
		this.y = y;
		this.size1 = mySize1;
		this.size2 = mySize2;
		this.color = generateColor(1);
		this.rad = 0.5;
		this.directionX = random(-1,1);
		this.directionY = random(-1,1);
		this.period = 0.1;
		this.dist = 0;
	}


	move() {
		 if (this.dist > 300)
		 {
			 	this.directionX = random([-1,1]);
		    this.directionY = random([-1,1]);
			 	this.directionX = random(-1,1);
		    this.directionY = random(-1,1);
			  this.dist = 0.0;
		 }

		this.size1 = frameCount % 50;
		this.size1 = this.size1 + cos(frameCount*this.period);
		this.x += this.directionX*cos(frameCount*0.01)*this.rad;
		this.y += this.directionY*sin(frameCount*0.01)*this.rad;

		this.dist += 1.0;
	}

	display() 
	{
		stroke(this.color);
		noFill();
		strokeWeight(1.5);
		drawCircle(this.x,this.y,this.size1,this.size2);
	}
}

function drawCircle(xx,yy,mySize1,mySize2)
{
	beginShape();
	for(let angle=0; angle < 2*PI;angle+=(Math.max(0.001, Math.abs((2*PI)) || 1))/200.0)
	{
		let x = xx + mySize1*cos(angle);
		let y = yy + mySize1*sin(angle);
		vertex(x,y);
	}
	beginContour();
	for(let angle=0; angle < 2*PI;angle+=(Math.max(0.001, Math.abs((2*PI)) || 1))/200.0)
	{
		var x = xx + mySize2*cos(angle);
		var y = yy + mySize2*sin(angle);
		vertex(x,y);
	}
	endContour();
	endShape(CLOSE);	
}


function generateColor(scale) {
	let temp = color(colors[floor(random(0,10))]);
	myColor = color(hue(window.color(temp)) + randomGaussian() * scale,
		saturation(window.color(temp)) + randomGaussian() * scale,
		brightness(window.color(temp)) + randomGaussian() * scale,
		random(10,100));
	return myColor;
}

function reduceB(myColor,scale) {
	temp = color(myColor);
	newColor = color(hue(window.color(temp)),saturation(window.color(temp)),brightness(window.color(temp)) - brightness(window.color(temp))*scale,random(10,100));
	return newColor;
}
